    categories:["Fedor von Bock","German field marshals","Army Group Center","Operation Barbarossa","German–Soviet War"],
    facts:[["Full name","Moritz Albrecht Franz Friedrich Fedor von Bock"],["Born","3 December 1880"],["Birthplace","Küstrin, Brandenburg"],["Service","Imperial Army · Reichswehr · Wehrmacht"],["First World War decoration","Pour le Mérite"],["Rank from July 1940","Generalfeldmarschall"],["1941 command","Army Group Center"],["Opening operations","Białystok–Minsk · Smolensk"],["Historical death","5 May 1945 · not retained"],["Post-August 1941 career","Open"]]
